#' @title Update  susiF via greedy search or backfit
#
#' @param obj a susiF object defined by init_susiF_obj function
#' @param X matrix of size n by p contains the covariates
#' @param min_purity minimum purity for estimated credible sets
#' @param verbose If \code{verbose = TRUE}, the algorithm's progress,
# and a summary of the optimization settings, are printed to the
# console.
#' @param cov_lev the desired level of converage
#' @return susiF object
#
#' @export
#' @keywords internal
#
#
greedy_backfit  <-  function(obj,
                             verbose,
                             cov_lev,
                             X,
                             min_purity,...  )
  UseMethod("greedy_backfit")

#' @rdname greedy_backfit
#
#' @method greedy_backfit susiF
#
#' @export greedy_backfit.susiF
#
#' @export
#' @keywords internal
greedy_backfit.susiF <-  function(obj,
                                  verbose,
                                  cov_lev,
                                  X,
                                  min_purity,...  )
{


  obj <- update_alpha_hist(obj)
  if(!(obj$greedy)&!(obj$backfit))
  {
    return(obj)
  }
  obj <- update_cal_cs(obj,
                       cov_lev=cov_lev)

  dummy.cs <-  which_dummy_cs(obj,
                              min_purity = min_purity,
                              median_crit=FALSE,
                              X=X,
                              lbf_min=obj$lbf_min)


  if(obj$backfit & (length(dummy.cs)>0)){

    obj$greedy <- FALSE
    if(length(dummy.cs)== obj$L){
      dummy.cs <- dummy.cs[-1]
      obj$backfit <- FALSE
    }
    if( length(dummy.cs)==0  )
    {
      obj$backfit <- FALSE
    }else{
      temp_L <- obj$L


      obj <- discard_cs(obj,
                        cs= dummy.cs,
                        out_prep= FALSE
      )

     # obj <- merge_effect (obj, verbose = verbose)

      if(verbose){
        print( paste( "Discarding ",(temp_L- obj$L), " effects"))
      }
    }
    return(obj)

  }##Conditions for stopping greedy search
  if(  (obj$L>obj$L_max))
  {

    obj$greedy <- FALSE



    obj <- discard_cs(obj,
                      cs= (obj$L_max+1):obj$L,
                      out_prep= FALSE
    )
   # obj <- merge_effect (obj, verbose = verbose)
    if(verbose){
      print( paste( "Discarding ",(obj$L_max- obj$L), " effects"))
      print( "Greedy search and backfitting done")
    }

  }

  if( length(dummy.cs)==0& !( obj$greedy))
  {
    obj$backfit <- FALSE
    #obj <- merge_effect (obj, verbose = verbose)
  }

  if(!(obj$greedy )&!(obj$backfit ) ){

    if(verbose){
      print( paste( "Discarding ",(obj$L_max- obj$L), " effects"))
      print( "Greedy search and backfitting done")
    }
    obj <- update_alpha_hist(obj,discard = TRUE)
    obj$greedy_backfit_update <- FALSE

    return(obj)
  }
  if(obj$greedy & (length(dummy.cs)==0)){

    tt <- obj$L_max -obj$L
    temp <- min( ifelse(tt>0,tt,0 ) , 7)

    if(temp==0){


      #obj <- merge_effect (obj, verbose = verbose)
      if(verbose){
        print( paste( "Discarding ",(obj$L_max- obj$L), " effects"))
        print( "Greedy search and backfitting done")
      }
      obj <- update_alpha_hist(obj,discard = TRUE)
      obj$greedy_backfit_update <- FALSE
      obj$backfit <- FALSE
      obj$greedy <- FALSE
      return(obj)
    }


    if(verbose){
      print( paste( "Adding ", temp, " extra effects"))
    }

    #obj <- merge_effect (obj, verbose = verbose)


    obj <- expand_susiF_obj(obj,L_extra = 7)
    return(obj)
  }

}




#' @title Initialize a susiF object using regression coefficients
#' @details  Initialize a susiF object using regression coefficients
#
#' @param L_max upper bound on the number of non zero coefficients An L-vector containing the indices of the
#   nonzero coefficients.
#
#' @param G_prior prior object defined by init_prior function
#
#' @param Y Matrix of outcomes
#
#' @param X matrix of covariatess
#
#' @param L_start number of effect to start with
#
#' @param greedy logical, if TRUE allow greedy search
#
#' @param backfit logical, if TRUE allow backfitting
#' @param tol_null_prior threshold to consider prior to be null. If the estimated weight on the point mass at zero is larger than 1-tol_null_prior
#' then set prior weight on point mass to be 1. In the mixture normal this corresponds to removing the effect. In the mixutre per scale prior this corresponds
#' to setting the prior of a given scale to at point mass at 0.
#' @param cov_lev numeric between 0 and 1, corresponding to the
#' expected level of coverage of the CS if not specified, set to 0.95
#' @param lbf_min numeric  discard low purity cs in the IBSS fitting procedure if the largest log Bayes factors is lower than this value
#' @param \dots Other arguments.
#
# @export
# @return A list with the following elements
# \item{fitted_wc}{ list of length L, each element contains the fitted wavelet coefficients of effect l}
# \item{fitted_wc2}{list of length L, each element contains the variance of the fitted wavelet coefficients of effect l}
# \item{alpha_hist}{ history of the fitted alpha value}
# \item{N}{ number of indidivual in the study}
# \item{sigma2}{residual variance}
# \item{n_wac}{number of wavelet coefficients}
# \item{ind_fitted_func}{fitted curves of each individual }
# \item{cs}{credible set}
# \item{pip}{Posterior inclusion probabilites}
# \item{G_prior}{a G_prior of the same class as the input G_prior, used for internal calculation}
# \item{lBF}{ log Bayes factor for the different effect}
# \item{KL}{ the KL divergence for the different effect}
# \item{ELBO}{ The evidence lower bound}
# \item{lfsr_wc}{Local fasle sign rate of the fitted wavelet coefficients}
#' @export
#
init_susiF_obj <- function(L_max,
                           G_prior,
                           Y,
                           X,
                           L_start,
                           greedy,
                           backfit,
                           tol_null_prior=0.001,
                           cov_lev=0.95,
                           lbf_min=0.1,
                           ... )
{



  fitted_wc       <- list()
  fitted_wc2      <- list()
  alpha           <- list()
  alpha_hist      <- list()
  ind_fitted_func <- matrix(0, nrow = dim(Y)[1], ncol=dim(Y)[2]  )
  cs              <- list()
  cred_band       <- list()
  pip             <- rep(0, dim(X)[2])
  est_pi          <- list()
  est_sd          <- list()
  L_max           <- L_max
  L               <- L_start
  G_prior         <- G_prior
  N               <- dim(Y)[1]
  n_wac           <- dim(Y)[2]
  P               <- dim(X)[2]
  sigma2          <- max(mean(apply(Y, 2, var)), sqrt(.Machine$double.eps))
  lBF             <- list()
  KL              <- rep(NA,L_start)
  ELBO            <- c()
  mean_X          <- attr(X, "scaled:center")
  csd_X           <- attr(X, "scaled:scale")
  d               <- attr(X , "d")
  n_expand        <- 0 #number of greedy expansion
  greedy          <- greedy
  backfit         <- backfit
  greedy_backfit_update <- FALSE
  lfsr_wc         <- list()
  for ( l in 1:L )
  {
    fitted_wc[[l]]        <-  matrix(0, nrow = dim(X)[2], ncol=dim(Y)[2]  )
    fitted_wc2[[l]]       <-  matrix(1, nrow = dim(X)[2], ncol=dim(Y)[2]  )
    alpha [[l]]           <-  rep(1/dim(X)[2], dim(X)[2])
    cs[[l]]               <-  list()
    est_pi [[l]]          <-  get_pi_G_prior(G_prior)
    est_sd [[l]]          <-  get_sd_G_prior(G_prior)
    lBF[[l]]              <-  rep(NA, ncol(X))
    cred_band[[l]]        <-  matrix(0, ncol = dim(Y)[2], nrow = 2)
  }
  obj <- list( fitted_wc       = fitted_wc,
               fitted_wc2      = fitted_wc2,
               lBF             = lBF,
               KL              = KL,
               cred_band       = cred_band,
               ELBO            = ELBO,
               ind_fitted_func = ind_fitted_func,
               G_prior         = G_prior,
               alpha_hist      = alpha_hist,
               N               = N,
               n_wac           = n_wac,
               sigma2          = sigma2,
               P               = P,
               alpha           = alpha,
               cs              = cs,
               pip             = pip,
               est_pi          = est_pi,
               est_sd          = est_sd,
               L               = L,
               L_max           = L_max,
               csd_X           = csd_X,
               n_expand        = n_expand,
               greedy          = greedy,
               backfit         = backfit,
               greedy_backfit_update=greedy_backfit_update,
               d               = d,
               lfsr_wc         = lfsr_wc,
               tol_null_prior  = tol_null_prior,
               cov_lev         = cov_lev,
               lbf_min         = lbf_min)

  class(obj) <- "susiF"
  return(obj)
}





#' @title Merging effect function
#
#' @param obj a susiF object defined by init_susiF_obj function
#
#
#' @param verbose logical
#' @param \dots Other arguments.
#
#
#' @return  a susiF object
#' @export
#' @keywords internal
merge_effect <- function( obj, verbose,  ...)
  UseMethod("merge_effect")

#' @rdname merge_effect
#
#' @method merge_effect susiF
#
#' @export merge_effect.susiF
#
#' @export
#' @keywords internal

merge_effect.susiF  <- function(obj, verbose = FALSE,  ...) {

  #return(obj)
  if (obj$L < 2) return(obj)

  to_drop <- integer(0)

  for (i in 1:(obj$L - 1)) {
    for (j in (i + 1):obj$L) {

      if (!(i %in% to_drop || j %in% to_drop) ){

        rel <- cs_relation(obj$cs[[i]], obj$cs[[j]])

        if ( !(rel == "none") ){
          largest <- which_cs_largeBF(obj, i, j)
          smallest  <- setdiff(c(i, j), largest)

          to_drop <- c(to_drop,  smallest )

          if (verbose) {
            message(
              sprintf(
                "Trivial merge: dropping effect %d (CS %s effect %d)",
                smallest,
                ifelse(rel == "identical", "identical to", "nested in"),
                largest
              )
            )
          }
        }


      }


    }
  }


  to_drop <- sort(unique(to_drop))
  if (length(to_drop) == 0) return(obj)

  discard_cs(obj, cs = to_drop, out_prep = FALSE)
}



# @title Updates CS names for output
#
# @param obj a susiF object defined by init_susiF_obj function
#
# @param X matrix of size N by p

name_cs <- function(obj,X,...)
  UseMethod("name_cs")

# @rdname name_cs
#
# @method name_cs susiF
#
# @export name_cs.susiF
#
#' @export
#' @keywords internal

name_cs.susiF <- function(obj,X,...){

  if( length(colnames(X))==ncol(X)){

    for (l in 1: length(obj$cs)){
      names(obj$cs[[l]]) <- colnames(X)[obj$cs[[l]]]
    }

  }
  return(obj)
}


#' @title Preparing output of main susiF function
#
#' @param  obj a susiF object defined by init_susiF_obj function
#
#' @param Y functional phenotype, matrix of size N by size J. The underlying algorithm uses wavelets that assume that J is of the form J^2. If J is not a power of 2, susiF internally remaps the data into a grid of length 2^J
#
#' @param X matrix of size N by p
#
#' @param indx_lst list generated by gen_wavelet_indx for the given level of resolution
#
#' @param filter_cs logical, if TRUE filter the credible set (removing low purity cs and cs with estimated prior equal to 0)
#
#' @param outing_grid grid use to fit fsusie
#'
#' @param pos the original position of the Y column
#'
#' @param verbose TRUE or FALSE verbose
#' @param tidx original positions of constant X columns excluded from fitting
#' @param kept_index original positions of X columns retained for fitting
#' @param original_P number of columns in the user-supplied X
#' @param names_colX original column names of X, if present
#' @return susiF object
#
#' @export
#' @keywords internal
out_prep <- function( obj, Y, X, indx_lst, outing_grid,...)
  UseMethod("out_prep")

#' @rdname out_prep
#
#' @method out_prep susiF
#
#' @export out_prep.susiF
#
#' @export
#' @keywords internal

out_prep.susiF <- function(obj ,
                           Y,
                           X,
                           indx_lst,
                           outing_grid,
                           filter_cs,

                           filter.number = 10,
                           family =  "DaubLeAsymm",
                           post_processing="TI",
                           tidx =NULL ,
                           kept_index = NULL,
                           original_P = NULL,
                           names_colX =NULL,
                           pos,
                           verbose=TRUE,
                           ...)
{




  obj <-  update_cal_pip(obj)
  if(filter_cs)
  {
    obj  <- check_cs(obj,
                     min_purity = 0.5,
                     X          = X
    )


    obj <-  merge_effect(obj)
    obj <- update_cal_pip(obj)
  }

  obj <-  name_cs(obj,X)


  obj <-  update_cal_fit_func(obj,
                              Y             =  Y,
                              X             = X,
                              indx_lst      = indx_lst,
                              post_processing = post_processing,
                              filter.number = filter.number,
                              family        = family)

  ## Reconstruct the per-individual fitted curves while alpha and X are still
  ## aligned in fitted-column space. Original-column formatting, which pads
  ## removed constant columns back into alpha, must remain the last operation.
  obj <-  update_cal_indf(obj      = obj,
                          Y        = Y,
                          X        = X,
                          indx_lst = indx_lst,
                          TI       = ifelse(post_processing %in% c('TI', 'smash'),
                                            TRUE, FALSE))

  obj             <-  rename_format_output (obj        = obj,
                                            names_colX = names_colX,
                                            tidx       = tidx,
                                            kept_index = kept_index,
                                            original_P = original_P)
  obj$outing_grid   <-  outing_grid
  # obj$purity        <-  cal_purity(l_cs= obj$cs, X=X)
  obj$original_grid <- pos
  return(obj)
}





.fs_expand_snp_vector <- function(x, kept_index, original_P, fill = 0,
                                  variable_names = NULL) {
  if (is.null(x)) {
    return(NULL)
  }
  if (length(x) != length(kept_index)) {
    stop("Internal error: SNP vector is not aligned with the fitted columns")
  }
  out <- rep(fill, original_P)
  out[kept_index] <- x
  if (!is.null(variable_names)) {
    names(out) <- variable_names
  }
  out
}

.fs_expand_snp_matrix_rows <- function(x, kept_index, original_P, fill = 0,
                                       variable_names = NULL) {
  if (is.null(x)) {
    return(NULL)
  }
  x <- as.matrix(x)
  if (nrow(x) != length(kept_index)) {
    stop("Internal error: SNP matrix rows are not aligned with the fitted columns")
  }
  out <- matrix(
    fill,
    nrow = original_P,
    ncol = ncol(x),
    dimnames = list(variable_names, colnames(x))
  )
  out[kept_index, ] <- x
  out
}

.fs_map_cs_to_original <- function(cs, kept_index, variable_names = NULL) {
  lapply(cs, function(index) {
    index <- as.integer(index)
    if (length(index) == 0L) {
      return(index)
    }
    if (anyNA(index) || any(index < 1L | index > length(kept_index))) {
      stop("Internal error: credible-set index is outside the fitted columns")
    }
    mapped <- kept_index[index]
    if (!is.null(variable_names)) {
      names(mapped) <- variable_names[mapped]
    }
    mapped
  })
}

rename_format_output <- function(obj, names_colX = NULL, tidx = integer(),
                                 kept_index = NULL, original_P = NULL, ...){
  if (identical(obj$column_index_space, "original")) {
    return(obj)
  }
  if (is.null(original_P)) {
    original_P <- obj$P + length(tidx)
  }
  if (is.null(kept_index)) {
    kept_index <- setdiff(seq_len(original_P), tidx)
  }
  kept_index <- as.integer(kept_index)
  fitted_P <- length(kept_index)
  if (obj$P != fitted_P ||
      anyNA(kept_index) ||
      anyDuplicated(kept_index) ||
      any(kept_index < 1L | kept_index > original_P)) {
    stop("Internal error: fitted object and covariate-column map disagree")
  }
  if (!is.null(names_colX) && length(names_colX) != original_P) {
    stop("Internal error: X column names and original column count disagree")
  }
  .fs_validate_effect_alignment(obj)

  expand_vector <- function(x, fill = 0) {
    .fs_expand_snp_vector(x, kept_index, original_P, fill, names_colX)
  }
  expand_rows <- function(x, fill = 0) {
    .fs_expand_snp_matrix_rows(x, kept_index, original_P, fill, names_colX)
  }

  original_cs <- .fs_map_cs_to_original(
    obj$cs,
    kept_index,
    variable_names = names_colX
  )
  obj$alpha <- lapply(obj$alpha, expand_vector, fill = 0)
  obj$pip <- expand_vector(obj$pip, fill = 0)
  obj$lBF <- lapply(obj$lBF, expand_vector, fill = -Inf)
  obj$fitted_wc <- lapply(obj$fitted_wc, expand_rows, fill = 0)
  obj$fitted_wc2 <- lapply(obj$fitted_wc2, expand_rows, fill = 0)

  if (!is.null(obj$alpha_hist)) {
    obj$alpha_hist <- lapply(obj$alpha_hist, function(snapshot) {
      if (is.list(snapshot)) {
        lapply(snapshot, function(x) {
          if (is.numeric(x) && length(x) == fitted_P) {
            expand_vector(x, 0)
          } else {
            x
          }
        })
      } else if (is.numeric(snapshot) && length(snapshot) == fitted_P) {
        expand_vector(snapshot, 0)
      } else {
        snapshot
      }
    })
  }

  obj$cs <- original_cs
  obj$csd_X <- expand_vector(obj$csd_X, fill = 1)
  obj$d <- expand_vector(obj$d, fill = 0)
  obj$fitted_P <- fitted_P
  obj$P <- original_P
  obj$original_P <- original_P
  obj$variable_index <- kept_index
  obj$removed_variable_index <- setdiff(seq_len(original_P), kept_index)
  obj$variable_names <- names_colX
  obj$column_index_space <- "original"

  if (!is.null(obj$fitted_func)) {
    names(obj$fitted_func) <- paste0(
      "fitted_function_effect_",
      seq_along(obj$fitted_func)
    )
  }
  obj$n_cs <- length(obj$cs)
  obj$cs_size <- lengths(obj$cs)
  .fs_validate_effect_alignment(obj)
  obj
}






#' @title Check tolerance for stopping criterion
#
#' @param obj a susiF object defined by init_susiF_obj function
#' @param check numeric, dynamic value for testing outing of th while loop
#' @param cal_obj logical, if set to TRUE compute ELBO
#
#' @param X matrix of covariates
#
#' @param D matrix of wavelet D coefficients from the original input data (Y)
#
#' @param C vector of wavelet scaling coefficient from the original input data (Y)
#
#' @param indx_lst list generated by gen_wavelet_indx for the given level of resolution
#
#' @return a matrix of size N by size J of partial residuals
#' @export
#' @keywords internal
test_stop_cond <- function(obj,
                           check,
                           cal_obj,
                           Y,
                           X,
                           D,
                           C,
                           indx_lst
                           ,...)
  UseMethod("test_stop_cond")

#' @rdname test_stop_cond
#
#' @method test_stop_cond susiF
#
#' @export test_stop_cond.susiF
#
#' @export
#' @keywords internal
test_stop_cond.susiF <- function(obj, check, cal_obj, Y, X, D, C, indx_lst,...)
{

  if( obj$L==1)
  {
    obj$check <- 0
    return(obj)
  }

  if(!(obj$greedy_backfit_update)) #if not just updated check for stopping while loop
  {
    if( cal_obj){

      obj <- update_KL(obj,
                       X,
                       D= D,
                       C= C , indx_lst)

      obj <- update_ELBO(obj,
                         get_objective( obj = obj,
                                        Y         = Y,
                                        X         = X,
                                        D         = D,
                                        C         = C,
                                        indx_lst  = indx_lst
                         )
      )

      if(length(obj$ELBO)>1    )#update parameter convergence,
      {
        check <- abs(diff(obj$ELBO)[(length( obj$ELBO )-1)])
        obj$check <- check
        return(obj)
      }else{
        obj$check <- check
        return(obj)
      }
    }
    else{
      len <- length( obj$alpha_hist)
      if( len>1)#update parameter convergence, no ELBO for the moment
      {
        check <-0

        T1 <- do.call( rbind, obj$alpha_hist[[len ]])
        T1 <- T1[1:obj$L,] #might be longer than L because alpha computed before discarding effect
        T2 <- do.call( rbind, obj$alpha_hist[[(len-1) ]])


        if(!(obj$L==nrow(T2))){
          obj$check=1
          return(obj)
        }
         if(obj$L==1){
          T2 <- T2[1,]
        }

        if((nrow(T1)>nrow(T2))){
          obj$check <- 1
          return(obj)
        }
        if( (nrow(T2)>nrow(T1))){
          T2 <- T2[1:obj$L,]
        }


        check <- max(abs(T1-T2)) #sum(abs(T1-T2))/nrow(X)

        obj$check <- check
        return(obj)
        #print(check)
      }else{
        obj$check <- check
        return(obj)
      }
    }
  }else{
    obj$check <- check
    return(obj)
  }

}





#' @title Update alpha   susiF mixture proportion of effect l
#
#' @param obj a susiF object defined by init_susiF_obj function
#
#' @param l integer larger or equal to 1. Corresponds to the effect to be accessed
#
#' @param alpha  vector of p alpha values summing up to one
#
#' @return susiF object
#
#' @export
#' @keywords internal

update_alpha  <-  function(obj, l, alpha,... )
  UseMethod("update_alpha")


#' @rdname update_alpha
#
#' @method update_alpha susiF
#
#' @export update_alpha.susiF
#
#' @export
#' @keywords internal
update_alpha.susiF <-  function(obj, l, alpha,... )
{
  obj$alpha[[l]] <- alpha
  return( obj)
}

#' @title Update alpha_hist   susiF object
#
#' @param obj a susiF object defined by init_susiF_obj function
#
#' @param  discard logical set to FALSE by default, if true remove element of history longer than L
#
#' @return susiF object
#
#' @export
#' @keywords internal

update_alpha_hist  <-  function(obj, discard,... )
  UseMethod("update_alpha_hist")


#' @rdname update_alpha_hist
#
#' @method update_alpha_hist susiF
#
#' @export update_alpha_hist.susiF
#
#' @export
#' @keywords internal
update_alpha_hist.susiF <-  function(obj , discard=FALSE,... )
{
  if(!discard){
    obj$alpha_hist[[ (length(obj$alpha_hist)+1)  ]] <- obj$alpha
  }
  if(discard){
    if((length(obj$alpha_hist[[length(obj$alpha_hist)]]) >obj$L)){

      tt <- obj$alpha_hist[[ (length(obj$alpha_hist) ) ]][1:obj$L]
      obj$alpha_hist[[ (length(obj$alpha_hist))  ]] <- tt
    }
  }

  return( obj)
}


# @title Update  susiF object using the output of EM_pi
#
# @description Update  susiF object using the output of EM_pi
#
# @param obj a susiF object defined by init_susiF_obj function
#
# @param l integer larger or equal to 1. Corresponds to the effect to be accessed
#
# @param EM_pi an object of the class "EM_pi" generated by the function \code{\link{EM_pi}}
#
# @param Bhat matrix of estimated regression coefficients
#
# @param Shat  matrix of estimated standard errors
#
# @param indx_lst list generated by gen_wavelet_indx for the given level of resolution
#
# @param lowc_wc list of wavelet coefficients that exhibit too little variance
#
# @param cal_wc_lsfr logical, set to TRUE if detailed output needed
#
# @return susiF object
#
# @export


update_susiF_obj  <- function(obj, l,
                              EM_pi,
                              Bhat,
                              Shat,
                              indx_lst,
                              lowc_wc=NULL,
                              cal_wc_lsfr=FALSE,
                              df=NULL,
                              cov_lev=0.95,
                              e=0.001,
                              ...)
  UseMethod("update_susiF_obj")

# @rdname update_susiF_obj
#
# @method update_susiF_obj susiF
#
# @export update_susiF_obj.susiF
#
#' @export
#' @keywords internal

update_susiF_obj.susiF <- function(obj,
                                   l,
                                   EM_pi,
                                   Bhat,
                                   Shat,
                                   indx_lst,
                                   lowc_wc=NULL,
                                   cal_wc_lsfr=FALSE,
                                   df=NULL,
                                   cov_lev=0.95,
                                   e=0.001,
                                   ...)
{

  if( l > length(obj$est_pi))
  {
    stop("Error trying to access mixture proportion")
  }
  if( l < 1)
  {
    stop("Error l should be larger ")
  }
  if(  "EM_pi"  %!in%  class(EM_pi)  )
  {
    stop("Error EM_pi should be of the class EM_pi")
  }
  obj         <-   update_pi(obj = obj ,
                             l = l ,
                             tpi =  EM_pi$tpi_k)
  obj$G_prior <-   update_prior(get_G_prior(obj) , EM_pi$tpi_k  )


  obj$fitted_wc[[l]]   <- post_mat_mean(get_G_prior(obj) ,
                                        Bhat,
                                        Shat,
                                        lBF      = EM_pi$lBF,
                                        indx_lst = indx_lst,
                                        lowc_wc  = lowc_wc,
                                        e        = e)
  obj$fitted_wc2[[l]]  <- post_mat_sd  (get_G_prior(obj) ,
                                        Bhat,
                                        Shat,
                                        lBF      = EM_pi$lBF,
                                        indx_lst = indx_lst,
                                        lowc_wc  = lowc_wc,
                                        e        = e)^2


  G_prior <- update_prior(G_prior = get_G_prior(obj),
                          tpi     = EM_pi$tpi_k )


  new_alpha <- cal_zeta(  EM_pi$lBF)

  obj  <- update_alpha (obj = obj,
                        l         = l,
                        alpha     = new_alpha)
  obj  <- update_lBF   (obj = obj,
                        l         = l,
                        lBF       = EM_pi$lBF)
  obj <-  update_cal_cs(obj=obj,  cov_lev=  cov_lev, l=l)
  # obj <-  update_lfsr  (obj=obj,
  #                             l=l ,
  #                            Bhat=Bhat,
  #                            Shat= Shat,
  #                            indx_lst=indx_lst)
  return(obj)
}

#' @title Update susiF by computing PiP
#
#' @param obj a susiF object defined by  init_susiF_obj  function
#' @return susiF object
#' @export
#' @keywords internal

update_cal_pip  <- function (obj,...)
  UseMethod("update_cal_pip")

#' @rdname update_cal_pip
#
#' @method update_cal_pip susiF
#
#' @export update_cal_pip.susiF
#
#' @export
#' @keywords internal

update_cal_pip.susiF <- function (obj,...)
{
  if(sum( is.na(unlist(obj$alpha))))
  {
    stop("Error: some alpha value not updated, please update alpha value first")
  }
  tpip <- list()
  for ( l in 1:obj$L)
  {
    tpip[[l]] <- rep(1, lengths(obj$alpha)[[l]])-obj$alpha[[l]]
  }
  obj$pip <- 1-  apply( do.call(rbind,tpip),2, prod)
  return(obj)
}

#' @title Update susiF by computing credible sets
#
#' @param obj a susiF object defined by  init_susiF_obj  function
#
#' @param cov_lev numeric between 0 and 1, corresponding to the expected level of coverage of the cs if not specified set to 0.95
#
#' @return susiF object
#
#' @export
#' @keywords internal
#'
update_cal_cs  <- function(obj, cov_lev=0.95,...)
  UseMethod("update_cal_cs")

#' @rdname update_cal_cs
#
#' @method update_cal_cs susiF
#
#' @export update_cal_cs.susiF
#
#' @export
#'
#' @keywords internal
#'
update_cal_cs.susiF <- function(obj, cov_lev=0.95, l,...)
{
  if( !missing(l)){
    if(sum( is.na(unlist(obj$alpha[[l]]))))
    {

      stop("Error: some alpha value not updated, please update alpha value first")
    }
    temp        <- obj$alpha[[l]]

    # check if temp has only 0 (i.e.  not yet updated)
    #  if(sum(temp==0)==length(temp)){
    temp_cumsum        <- cumsum( temp[order(temp, decreasing =TRUE)])
    max_indx_cs        <- min(c(which( temp_cumsum >cov_lev ), obj$P))
    obj$cs[[l]]        <- order(temp, decreasing = TRUE)[1:max_indx_cs ]
    return(obj)
  }

  if(sum( is.na(unlist(obj$alpha))))
  {
    stop("Error: some alpha value not updated, please update alpha value first")
  }
  for ( l in 1:obj$L)
  {
    temp        <- obj$alpha[[l]]

    # check if temp has only 0 (i.e.  not yet updated)
    #  if(sum(temp==0)==length(temp)){
    temp_cumsum <- cumsum( temp[order(temp, decreasing =TRUE)])
    max_indx_cs <-  min(c(which( temp_cumsum >cov_lev ), obj$P))
    obj$cs[[l]]  <- order(temp, decreasing = TRUE)[1:max_indx_cs ]
    names(obj$cs[[l]]) <- names(obj$alpha[[l]])[obj$cs[[l]]]
  }

  return(obj)
}

#@title Update susiF by computing predicted curves
#
#@param obj a susiF object defined by init_susiF_obj function
#@param Y functional phenotype, matrix of size N by size J. The underlying algorithm uses wavelet which assume that J is of the form J^2. If J not a power of 2, susiF internally remaps the data into grid of length 2^J
#@param X matrix of size N by p
#@param indx_lst list generated by gen_wavelet_indx for the given level of resolution
#@return susiF object
#@export
#

update_cal_indf <- function(obj, Y, X, indx_lst, TI=FALSE,...)
  UseMethod("update_cal_indf")

# @rdname update_cal_indf
#
# @method update_cal_indf susiF
#
# @export update_cal_indf.susiF
#
#
# @export
#
#' @importFrom wavethresh wr
#' @importFrom wavethresh wd
update_cal_indf.susiF <- function(obj, Y, X, indx_lst, TI = FALSE, ...) {

  N <- nrow(Y)
  J <- ncol(Y)

  ## Per-individual fitted curves via the lead-SNP post-processed effects.
  ##
  ## IMPORTANT (offset handling): before the wavelet regression, BOTH Y and
  ## X are column-centred (and scaled) by colScale(., center = TRUE). The
  ## post-processed effect curves obj$fitted_func[[l]] are therefore slopes
  ## estimated on CENTRED data, already expressed in original-Y-per-
  ## original-X units (the post-processors divide by csd_X and multiply by
  ## csd_Y). To reconstruct an individual's curve on the original scale we
  ## must (i) add back the per-position column mean of Y removed by the
  ## centring, and (ii) centre X by its own column means so the lead-SNP
  ## contribution is measured relative to the same origin:
  ##
  ##   yhat_i(t) = mean_t(Y) + sum_l ( X[i, j_l] - mean(X[, j_l]) ) * f_l(t)
  ##
  ## with j_l = which.max(alpha_l) the lead SNP of effect l. The previous
  ## implementation omitted the X-centring and multiplied by
  ## attr(X, "scaled:scale"), which is NULL at the out_prep() call site
  ## (X is passed unscaled there) -- so the slot stayed at its zero init.
  offset_t   <- colMeans(Y)                       # per-position Y offset
  ind_fitted <- matrix(offset_t, nrow = N, ncol = J, byrow = TRUE)

  ## Only effects that have a post-processed curve (one per surviving CS).
  L_fit <- length(obj$fitted_func)
  if (L_fit == 0L) {
    obj$ind_fitted_func <- ind_fitted
    return(obj)
  }

  X_centered <- sweep(X, 2, colMeans(X), "-")

  for (l in seq_len(L_fit)) {
    j   <- which.max(obj$alpha[[l]])              # lead SNP of effect l
    f_l <- as.numeric(obj$fitted_func[[l]])       # 1 x J post-processed curve
    ind_fitted <- ind_fitted + outer(X_centered[, j], f_l)
  }

  obj$ind_fitted_func <- ind_fitted
  obj
}




#' @title Update susiF by computing posterior curves
#
#' @param  obj a susiF/EBmvFR object defined by init_susiF_obj function
#' @param Y  functional phenotype, matrix of size N by size J. The underlying algorithm uses wavelet which assume that J is of the form J^2. If J not a power of 2, susif internally remaps the data into grid of length 2^J
#
#' @param X matrix of size n by p in
#
#' @param indx_lst list generated by gen_wavelet_indx for the given level of resolution
#'
#'@param filter.number see documentation of wd from wavethresh package
#'@param family see documentation of wd from wavethresh package
#' @return susiF object
#
#' @export
#' @keywords internal
update_cal_fit_func  <- function( obj, indx_lst,  ...)
  UseMethod("update_cal_fit_func")

#' @rdname update_cal_fit_func
#
#' @method update_cal_fit_func susiF
#
#' @export update_cal_fit_func.susiF
#
#' @importFrom wavethresh wr
#
#' @importFrom wavethresh wd
#
#' @export
#' @keywords internal

update_cal_fit_func.susiF <- function(obj,
                                      indx_lst,
                                      Y,
                                      X,
                                      post_processing="TI",
                                      filter.number = 10,
                                      family = "DaubLeAsymm" ,
                                      verbose=TRUE,
                                      ...)
{


  if(sum( is.na(unlist(obj$alpha))))
  {
    stop("Error: some alpha value not updated, please update alpha value first")
  }


  dummy_cs = which_dummy_cs(obj, min_purity=0.5 ,X)

  #if( obj$L==1 &   1 %in% dummy_cs ){

  #  obj$fitted_func[[1]] = rep(0 , ncol(Y))
  #  return(obj)
  #}


  if ( post_processing == "TI"){

    obj <- TI_regression(obj=obj,
                         Y=Y,
                         X=X,
                         filter.number = 1 ,
                         family = "DaubExPhase",
                         verbose= verbose

    )
  }
  if( post_processing =="HMM"){
    obj <- HMM_regression(obj=obj,
                          Y=Y,
                          X=X,
                          verbose= verbose
    )
    obj$cred_band <- NULL
  }
  if(post_processing=="smash"){

    obj <- smash_regression(obj=obj,
                            Y=Y,
                            X=X,
                            filter.number = filter.number,
                            family = family,
                            verbose= verbose

    )
  }
  if( post_processing=="none"){
    ## "vanilla" wavelet effect estimate: no resmoothing, just invert all
    ## the standardisation that was applied before IBSS so that
    ## fitted_func[[l]] is on the same scale as the input Y.
    ##
    ## Scaling chain in susiF():
    ##   X        scaled by csd_X     (per SNP)
    ##   Y        scaled by csd_Y_pos (per outcome position)  [stored on obj]
    ##   Y_f      = wavelet(scaled Y), then scaled by csd_Yf  (per wavelet coef)
    ##
    ## fitted_wc[[l]] lives in the fully-standardised space, so to recover
    ## an effect curve in the original Y units we need:
    ##   (i)   weight by alpha and divide by csd_X     (collapse over SNPs)
    ##   (ii)  multiply each wavelet coefficient by csd_Yf
    ##   (iii) inverse wavelet transform
    ##   (iv)  multiply per-position by csd_Y_pos
    ## The previous code did only (i) and (iii); the missing csd_Yf and
    ## csd_Y_pos factors caused fitted_func to come out shrunk by a factor
    ## of roughly csd_Y_pos (~5x in typical genotype noise simulations).

    temp <- wavethresh::wd(rep(0, obj$n_wac))

    csd_Yf    <- obj$csd_Yf
    csd_Y_pos <- obj$csd_Y_pos

    last_idx <- indx_lst[[length(indx_lst)]]
    is_per_scale <- inherits(get_G_prior(obj), "mixture_normal_per_scale")
    is_normal    <- inherits(get_G_prior(obj), "mixture_normal")

    if (is_per_scale || is_normal) {
      ## Both prior families use the same back-conversion; the only
      ## historic difference was the index vector for the C-coefficient.
      C_idx <- if (is_per_scale) last_idx else dim(obj$fitted_wc[[1]])[2]

      for (l in 1:obj$L) {

        ## (i) collapse over SNPs with alpha and undo X scaling
        wc_collapsed <- (obj$alpha[[l]] / obj$csd_X) %*% obj$fitted_wc[[l]]
        wc_collapsed <- as.numeric(wc_collapsed)        # length n_wac

        ## (ii) undo Y_f wavelet-coefficient scaling
        if (!is.null(csd_Yf)) wc_collapsed <- wc_collapsed * csd_Yf

        temp$D                 <- wc_collapsed[-C_idx]
        temp$C[length(temp$C)] <- wc_collapsed[ C_idx]

        ## (iii) inverse wavelet transform, then (iv) undo Y per-position scaling
        f_hat <- wavethresh::wr(temp)
        if (!is.null(csd_Y_pos)) f_hat <- f_hat * csd_Y_pos

        obj$fitted_func[[l]] <- f_hat
      }
    }
  }


  return(obj)
}


# @title Update susiF by computing credible band for posterior curves
#
# @param obj a susiF object defined by init_susiF_obj function
#
# @param indx_lst list generated by gen_wavelet_indx for the given level of resolution
#
# @return susiF object
#
# @export
update_cal_credible_band  <- function(obj, indx_lst,...)
  UseMethod("update_cal_credible_band")

# @rdname  update_cal_credible_band
#
# @method  update_cal_credible_band susiF
#
# @export  update_cal_credible_band.susiF
#
# @importFrom wavethresh wr
#
# @importFrom wavethresh wd
# @importFrom wavethresh GenW
#
#' @export
#' @keywords internal

update_cal_credible_band.susiF <- function(obj, indx_lst,...)
{

  if(sum( is.na(unlist(obj$alpha))))
  {
    stop("Error: some alpha value not updated, please update alpha value first")
  }
  temp <- wavethresh::wd(rep(0, obj$n_wac))


  for ( l in 1:obj$L)
  {
    Smat <-  obj$fitted_wc2[[l]]
    W1   <- ((wavethresh::GenW(n=  ncol(Smat )  , filter.number = 10, family = "DaubLeAsymm")))
    tt   <- diag( W1%*%diag(c(obj$alpha[[l]]%*%Smat ))%*% t(W1 ))

    up                       <-  obj$fitted_func[[l]]+ 3*sqrt(tt)#*sqrt(obj$N-1)
    low                      <-  obj$fitted_func[[l]]- 3*sqrt(tt)#*sqrt(obj$N-1)
    obj$cred_band[[l]] <- rbind(up, low)
  }



  return(obj)
}




#' @title Update susiF lfsr effect
#'
#' @param obj a susiF object defined by init_susiF_obj function
