#'
update_lfsr_effect  <- function    (obj ,...)
  UseMethod("update_lfsr_effect")

#' @rdname update_lfsr_effect
#
#' @method update_lfsr_effect susiF
#
#' @export update_lfsr_effect.susiF
#
#' @export
#'
