#
#' @title Return which credible sets are  dummy
#
#' @param obj a susif object defined by init_susiF_obj function
#' @param min_purity minimal purity within a CS
#' @param X matrix of covariates
#' @param median_crit remove cs base on max absolute correlation instead of min absolute correlation, usefull in the
#' @param lbf_min cirteria for in the ly cs removal
#' @return a list of index corresponding the the dummy effect
#
#' @export
#' @keywords internal
which_dummy_cs <- function(obj, min_purity=0.5,X,median_crit=FALSE,lbf_min,...)
  UseMethod("which_dummy_cs")



#' @rdname which_dummy_cs
#
#' @method which_dummy_cs susiF
#
#' @export which_dummy_cs.susiF
#' @export
#' @keywords internal
which_dummy_cs.susiF <- function(obj, min_purity=0.5,X,median_crit=FALSE,lbf_min,...){

  dummy.cs<- c()
  # if( obj$L==1){
  #   return(dummy.cs)
  # }

  if (missing(lbf_min)){
    lbf_min=Inf
  }
  f_crit <- function (obj, min_purity=0.5, l, median_crit=FALSE,lbf_min){
    cs_l <- obj$cs[[l]]
    if (length(cs_l) == 0L) {
      return(TRUE)
    }
    if (median_crit && length(cs_l) < 5L) {
      return(FALSE)
    }

    if (length(cs_l) == 1L) {
      purity <- 1
    } else {
      correlation <- suppressWarnings(stats::cor(
        X[, cs_l, drop=FALSE]
      ))
      off_diagonal <- abs(correlation[lower.tri(correlation)])
      if (length(off_diagonal) == 0L ||
        any(!is.finite(off_diagonal))) {
        purity <- -Inf
      } else if (median_crit) {
        purity <- stats::median(off_diagonal)
      } else {
        purity <- min(off_diagonal)
      }
    }

    effect_lbf <- obj$lBF[[l]]
    max_lbf <- if (any(is.finite(effect_lbf))) {
      max(effect_lbf[is.finite(effect_lbf)])
    } else {
      -Inf
    }
    isTRUE(purity < min_purity && max_lbf < lbf_min)
  }





  if( inherits( obj$G_prior,"mixture_normal"))
  {
    for (l in 1:obj$L )
    {

      if (length(obj$cs[[l]])==1)
      {

        if( obj$est_pi[[l]][1]>1-obj$tol_null_prior){# check if the estimated prior is exactly 0

          dummy.cs<-  c( dummy.cs,l)
        }

      }else{

        if(   f_crit(obj = obj,
                     min_purity=min_purity,
                     l=l,
                     median_crit=median_crit,
                     lbf_min=lbf_min ) ){#check if the purity of cs l is lower that min_purity

          dummy.cs<-  c( dummy.cs,l)

        }else{
          if(obj$est_pi[[l]][1]>1-obj$tol_null_prior){
            dummy.cs<-  c( dummy.cs,l)
          }

        }
      }

    }


    return(dummy.cs)

  }

  if(inherits(obj$G_prior,"mixture_normal_per_scale"))
  {
    for (l in 1:obj$L )
    {

      if (length(obj$cs[[l]])==1)
      {

        if(  mean(sapply(obj$est_pi[[l]],"[[",1))>1-obj$tol_null_prior){# check if the estimated prior is exactly 0

          dummy.cs<-  c( dummy.cs,l)
        }

      }else{

        if(  f_crit(obj = obj,
                    min_purity=min_purity,
                    l=l,
                    median_crit=median_crit,
                    lbf_min=lbf_min )){#check if the purity of cs l is lower that min_purity

          dummy.cs<-  c( dummy.cs,l)

        }else{
          if(  mean(sapply(obj$est_pi[[l]],"[[",1))> 1-obj$tol_null_prior){
            dummy.cs<-  c( dummy.cs,l)
          }

        }
      }

    }

    return(dummy.cs)

  }

}





#' @title which_cs_largeBF
#' @param   l1 cs1
#' @param   l2 cs2
#' @export
#' @keywords internal
which_cs_largeBF <- function(obj, l1, l2) {
  cs1 <- obj$cs[[l1]]
  cs2 <- obj$cs[[l2]]

  if (length(cs1) < length(cs2)) return(l1)
  if (length(cs2) < length(cs1)) return(l2)

  bf1 <- max(obj$lBF[[l1]], na.rm = TRUE)
  bf2 <- max(obj$lBF[[l2]], na.rm = TRUE)

  if (bf1 > bf2) return(l1)
  if (bf2 > bf1) return(l2)

  return(min(l1, l2))
}
